uml:
@startuml BP01_Procurement_Inbound
title BP-01 - Quy trình Mua hàng và Nhập kho

scale 2000 width

skinparam backgroundColor #FFFFFF
skinparam defaultFontName Arial
skinparam defaultFontSize 15
skinparam shadowing false
skinparam roundcorner 10
skinparam activity {
    BackgroundColor #F8F9FA
    BorderColor #374151
    FontColor #111827
    ArrowColor #4B5563
}
skinparam swimlane {
    BorderColor #6B7280
    TitleBackgroundColor #E5E7EB
}

|Nhân viên kho|
start
:Kiểm tra tình hình tồn kho;
:Xác định hàng hóa cần bổ sung;
:Lập yêu cầu mua hàng;

|Kế toán|
:Tiếp nhận yêu cầu mua hàng;
:Xác nhận nhu cầu mua;
:Liên hệ nhà cung cấp;
:Đặt hàng với nhà cung cấp;

|Nhà cung cấp|
:Xác nhận đơn đặt hàng;
:Chuẩn bị hàng;
:Giao hàng và chứng từ;

|Nhân viên kho|
:Tiếp nhận hàng;
:Kiểm đếm hàng thực tế;
:Nhập hàng vào kho;
:Xác nhận kết quả nhận hàng;

|Kế toán|
:Tiếp nhận chứng từ mua hàng;
:Đối chiếu hàng nhận và chứng từ;
:Ghi nhận công nợ / thanh toán;
:Hoàn tất nghiệp vụ mua hàng;

stop
@enduml

@startuml BP02_Internal_Transfer
title BP-02 - Quy trình Điều chuyển hàng giữa các kho

scale 2000 width

skinparam backgroundColor #FFFFFF
skinparam defaultFontName Arial
skinparam defaultFontSize 15
skinparam shadowing false
skinparam roundcorner 10
skinparam activity {
    BackgroundColor #F8F9FA
    BorderColor #374151
    FontColor #111827
    ArrowColor #4B5563
}
skinparam swimlane {
    BorderColor #6B7280
    TitleBackgroundColor #E5E7EB
}

|Nhân viên kho nhận|
start
:Xác định nhu cầu bổ sung hàng;
:Lập yêu cầu điều chuyển hàng;

|Nhân viên kho xuất|
:Tiếp nhận yêu cầu điều chuyển;
:Chuẩn bị hàng cần điều chuyển;
:Kiểm đếm hàng xuất;
:Bàn giao hàng điều chuyển;

|Nhân viên giao hàng|
:Tiếp nhận hàng;
:Vận chuyển hàng đến kho nhận;
:Bàn giao hàng;

|Nhân viên kho nhận|
:Tiếp nhận hàng điều chuyển;
:Kiểm đếm số lượng thực nhận;
:Nhập hàng vào kho;
:Xác nhận hoàn tất điều chuyển;

stop
@enduml

@startuml BP03_Sales_Delivery
title BP-03 - Quy trình Bán hàng và Giao hàng

scale 2000 width

skinparam backgroundColor #FFFFFF
skinparam defaultFontName Arial
skinparam defaultFontSize 15
skinparam shadowing false
skinparam roundcorner 10
skinparam activity {
    BackgroundColor #F8F9FA
    BorderColor #374151
    FontColor #111827
    ArrowColor #4B5563
}
skinparam swimlane {
    BorderColor #6B7280
    TitleBackgroundColor #E5E7EB
}

|Khách hàng|
start
:Cung cấp nhu cầu mua hàng;

|Nhân viên bán hàng|
:Tư vấn sản phẩm;
:Xác nhận sản phẩm và số lượng;
:Lập đơn bán hàng;

|Thu ngân|
:Tiếp nhận thông tin thanh toán;
:Thu tiền khách hàng;
:Xác nhận thanh toán;

|Nhân viên kho|
:Tiếp nhận yêu cầu xuất hàng;
:Chuẩn bị hàng;
:Kiểm đếm số lượng xuất;
:Bàn giao hàng cho nhân viên giao hàng;

|Nhân viên giao hàng|
:Tiếp nhận hàng;
:Vận chuyển hàng đến khách hàng;

|Khách hàng|
:Kiểm nhận hàng;
:Xác nhận nhận hàng;

|Nhân viên giao hàng|
:Ghi nhận số lượng đã bàn giao;
:Hoàn tất giao hàng;

|Kế toán|
:Đối chiếu số lượng giao thực tế;
:Lập hóa đơn theo hàng thực giao;
:Ghi nhận doanh thu;

stop
@enduml

@startuml BP04_Customer_Return
title BP-04 - Quy trình Khách hàng Trả hàng

scale 2000 width

skinparam backgroundColor #FFFFFF
skinparam defaultFontName Arial
skinparam defaultFontSize 15
skinparam shadowing false
skinparam roundcorner 10
skinparam activity {
    BackgroundColor #F8F9FA
    BorderColor #374151
    FontColor #111827
    ArrowColor #4B5563
}
skinparam swimlane {
    BorderColor #6B7280
    TitleBackgroundColor #E5E7EB
}

|Khách hàng|
start
:Yêu cầu trả hàng;
:Bàn giao hàng cần trả;

|Nhân viên bán hàng|
:Tiếp nhận yêu cầu trả hàng;
:Xác nhận thông tin đơn bán;

|Nhân viên kho|
:Tiếp nhận hàng trả;
:Kiểm đếm và kiểm tra hàng;
:Nhập lại hàng vào kho;
:Xác nhận số lượng hàng nhận lại;

|Kế toán|
:Tiếp nhận kết quả trả hàng;
:Điều chỉnh chứng từ bán hàng;
:Xác định số tiền hoàn trả;

|Thu ngân|
:Thực hiện hoàn tiền cho khách hàng;

|Khách hàng|
:Nhận tiền hoàn;
:Xác nhận hoàn tất trả hàng;

stop
@enduml

@startuml BP05_Supplier_Return
title BP-05 - Quy trình Trả hàng Nhà cung cấp

scale 2000 width

skinparam backgroundColor #FFFFFF
skinparam defaultFontName Arial
skinparam defaultFontSize 15
skinparam shadowing false
skinparam roundcorner 10
skinparam activity {
    BackgroundColor #F8F9FA
    BorderColor #374151
    FontColor #111827
    ArrowColor #4B5563
}
skinparam swimlane {
    BorderColor #6B7280
    TitleBackgroundColor #E5E7EB
}

|Nhân viên kho|
start
:Xác định hàng cần trả nhà cung cấp;
:Ghi nhận số lượng hàng cần trả;
:Gửi thông tin trả hàng;

|Kế toán|
:Tiếp nhận thông tin hàng trả;
:Đối chiếu đơn mua và chứng từ;
:Liên hệ nhà cung cấp;
:Xác nhận phương án trả hàng;

|Nhân viên kho|
:Chuẩn bị hàng trả;
:Kiểm đếm hàng;
:Bàn giao hàng trả;

|Nhân viên giao hàng|
:Tiếp nhận hàng;
:Vận chuyển đến nhà cung cấp;
:Bàn giao hàng;

|Nhà cung cấp|
:Tiếp nhận hàng trả;
:Xác nhận số lượng nhận lại;
:Phát hành chứng từ điều chỉnh;

|Kế toán|
:Tiếp nhận chứng từ điều chỉnh;
:Đối chiếu công nợ;
:Điều chỉnh giá trị mua hàng;
:Hoàn tất nghiệp vụ trả hàng;

stop
@enduml

@startuml BP06_Stock_Count
title BP-06 - Quy trình Kiểm kê và Điều chỉnh tồn kho

scale 2000 width

skinparam backgroundColor #FFFFFF
skinparam defaultFontName Arial
skinparam defaultFontSize 15
skinparam shadowing false
skinparam roundcorner 10
skinparam activity {
    BackgroundColor #F8F9FA
    BorderColor #374151
    FontColor #111827
    ArrowColor #4B5563
}
skinparam swimlane {
    BorderColor #6B7280
    TitleBackgroundColor #E5E7EB
}

|Kế toán|
start
:Lập kế hoạch kiểm kê;
:Xác định phạm vi kiểm kê;
:Thông báo thực hiện kiểm kê;

|Nhân viên kho|
:Chuẩn bị khu vực kiểm kê;
:Kiểm đếm hàng hóa thực tế;
:Ghi nhận kết quả kiểm kê;
:Tổng hợp số lượng thực tế;

|Kế toán|
:Tiếp nhận kết quả kiểm kê;
:Đối chiếu số liệu;
:Lập biên bản kiểm kê;
:Ghi nhận điều chỉnh tồn kho;
:Ghi nhận giá trị chênh lệch;

|Nhân viên kho|
:Xác nhận số liệu tồn sau kiểm kê;

|Kế toán|
:Hoàn tất kỳ kiểm kê;

stop
@enduml
